<style>
:root{--dlr-blue:#0757d6;--dlr-blue2:#0e67e8;--dlr-bg:#f5f8fd;--dlr-navy:#0b1739;--dlr-border:#e2e8f2;--dlr-muted:#667085;--dlr-green:#0aa557;--dlr-orange:#ff6b16;--dlr-purple:#7b2be2;--dlr-red:#ea334b}
.content-wrapper{background:var(--dlr-bg)!important}.content-header{padding:22px 24px 8px!important}.content-header h1{font-size:28px!important;font-weight:800!important;color:var(--dlr-navy)!important;letter-spacing:-.4px}.content{padding:14px 24px 30px!important}.box{border:1px solid var(--dlr-border)!important;border-radius:14px!important;box-shadow:0 7px 22px rgba(15,23,42,.055)!important;overflow:visible!important;background:#fff!important}.box.box-primary,.box.box-danger{border-top:1px solid var(--dlr-border)!important}.box-header{padding:17px 20px!important;border-bottom:1px solid #edf1f7!important}.box-title{font-size:18px!important;font-weight:800!important;color:var(--dlr-navy)!important}.box-body{padding:20px!important}.form-control{height:42px!important;border:1px solid #d8e0ec!important;border-radius:9px!important;box-shadow:none!important;padding:9px 12px!important}.form-control:focus{border-color:#3478e5!important;box-shadow:0 0 0 3px rgba(52,120,229,.10)!important}textarea.form-control{height:auto!important;min-height:86px}label{font-weight:700!important;color:#1f2a44!important;margin-bottom:7px!important}.btn{border-radius:9px!important;font-weight:700!important;padding:9px 14px!important;border-width:1px!important}.btn-primary{background:linear-gradient(135deg,#0b59dc,#1088e8)!important;border-color:#0b59dc!important}.btn-success{background:#0aa557!important}.btn-warning{background:#ff9e20!important;color:#111!important}.btn-info{background:#128acb!important}.table-responsive{border:0!important}.table{margin-bottom:12px!important;border-collapse:separate!important;border-spacing:0!important}.table thead th{background:#f6f8fc!important;color:#1c2a48!important;font-size:13px!important;font-weight:800!important;text-transform:uppercase!important;letter-spacing:.2px!important;border-top:1px solid var(--dlr-border)!important;border-bottom:1px solid var(--dlr-border)!important;padding:12px 10px!important;white-space:normal!important;vertical-align:middle!important}.table tbody td{padding:11px 10px!important;vertical-align:middle!important;border-top:0!important;border-bottom:1px solid #edf1f6!important}.table-bordered{border:0!important}.table-bordered>thead>tr>th,.table-bordered>tbody>tr>td{border-left:0!important;border-right:0!important}.pagination>li>a,.pagination>li>span{border-radius:8px!important;margin:0 3px!important;border-color:#dde4ee!important;color:#25406c!important}.small-box{background:#fff!important;color:var(--dlr-navy)!important;border:1px solid var(--dlr-border)!important;border-radius:14px!important;box-shadow:0 7px 22px rgba(15,23,42,.055)!important;min-height:142px!important;overflow:hidden!important;position:relative}.small-box .inner{padding:20px!important}.small-box h3{font-size:30px!important;color:#0757d6!important;margin:0 0 6px!important}.small-box p{font-weight:800!important;font-size:14px!important}.small-box .icon{top:19px!important;right:20px!important;font-size:46px!important;color:rgba(7,87,214,.16)!important}.small-box:after{content:"";position:absolute;left:0;right:0;bottom:0;height:4px;background:linear-gradient(90deg,#0757d6,#18a0fb)}.alert{border-radius:11px!important;border:1px solid #d6e6ff!important;box-shadow:none!important}.label{border-radius:999px!important;padding:5px 9px!important;font-size:11px!important}.dlr-std-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 14px;padding:12px;border:1px solid var(--dlr-border);border-radius:12px;background:#fff}.dlr-std-toolbar .dlr-search{min-width:230px;max-width:330px;flex:1;height:40px;border:1px solid #d8e0ec;border-radius:9px;padding:8px 12px}.dlr-std-toolbar button,.dlr-std-toolbar select,.dlr-std-toolbar input[type=date]{height:40px;border:1px solid #d8e0ec;border-radius:9px;background:#fff;padding:7px 10px;font-weight:700;color:#24324c}.dlr-std-toolbar button:hover{background:#f2f6fc}.dlr-col-menu{position:relative}.dlr-col-popup{display:none;position:absolute;z-index:50;top:44px;right:0;min-width:220px;background:#fff;border:1px solid var(--dlr-border);border-radius:10px;box-shadow:0 12px 35px rgba(0,0,0,.12);padding:10px}.dlr-col-popup.show{display:block}.dlr-col-popup label{display:block!important;font-weight:600!important;font-size:12px!important;margin:6px!important}.dlr-empty{text-align:center!important;color:#7d879b!important;padding:28px!important}.dlr-num{text-align:right!important;font-variant-numeric:tabular-nums}.dlr-note-btn{border:1px solid #d7dfeb;border-radius:8px;background:#fff;padding:5px 9px;font-weight:700;color:#185fc1}.dlr-modal-backdrop{display:none;position:fixed;inset:0;background:rgba(5,14,38,.48);z-index:99998;align-items:center;justify-content:center}.dlr-modal-backdrop.show{display:flex}.dlr-modal{width:min(520px,92vw);background:#fff;border-radius:15px;padding:22px;box-shadow:0 22px 70px rgba(0,0,0,.28)}.dlr-modal h3{margin:0 0 12px;font-weight:800}.dlr-modal-close{float:right;border:0;background:#f04438;color:#fff;border-radius:8px;padding:6px 10px}.dlr-select-search{font-size:12px;height:34px!important;margin-bottom:5px}.well{border-radius:10px!important;background:#f8faff!important;border-color:#e4eaf3!important;box-shadow:none!important;font-weight:700!important}.dlr-form-note{margin-top:16px}.dlr-page-intro{color:#667085;margin:4px 0 16px;font-size:14px}.dlr-quick-card{display:flex;align-items:center;gap:10px;border:1px solid var(--dlr-border);border-radius:11px;padding:14px;background:#fff;min-height:58px;font-weight:800;color:#13264b}.dlr-quick-card i{width:34px;height:34px;border-radius:9px;background:#edf4ff;color:#0757d6;display:inline-flex;align-items:center;justify-content:center}.dlr-quick-card:hover{box-shadow:0 8px 18px rgba(15,23,42,.07);transform:translateY(-1px)}
@media(max-width:767px){.content{padding:12px!important}.content-header{padding:16px 12px 4px!important}.content-header h1{font-size:22px!important}.dlr-std-toolbar .dlr-search{min-width:100%;max-width:none}}
</style>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var qPrec={{ $dlrQuantityPrecision }}, cPrec={{ $dlrCurrencyPrecision }};
 function parseNum(v){var n=parseFloat(String(v).replace(/,/g,'').trim());return isNaN(n)?null:n}
 document.querySelectorAll('.table').forEach(function(table,ti){
   var wrap=table.closest('.box-body')||table.parentNode;if(!wrap||wrap.querySelector(':scope > .dlr-std-toolbar'))return;
   var bar=document.createElement('div');bar.className='dlr-std-toolbar';
   bar.innerHTML='<input class="dlr-search" placeholder="Universal Search...">'+
   '<select class="dlr-range" title="Date Range"><option value="">All Dates</option><option value="this_year">This Year</option><option value="last_year">Last Year</option><option value="this_fy">This FY</option><option value="last_fy">Last FY</option><option value="custom">Custom</option></select><input type="date" class="dlr-from" title="From"><input type="date" class="dlr-to" title="To">'+
   '<select class="dlr-page-size" title="Transactions per page"><option>10</option><option>25</option><option selected>50</option><option>100</option></select>'+
   '<button type="button" class="dlr-csv"><i class="fa fa-file-text-o"></i> CSV</button><button type="button" class="dlr-xls"><i class="fa fa-file-excel-o"></i> Excel</button>'+
   '<button type="button" class="dlr-print"><i class="fa fa-print"></i> Print</button><button type="button" class="dlr-pdf"><i class="fa fa-file-pdf-o"></i> PDF</button>'+
   '<button type="button" class="dlr-email"><i class="fa fa-envelope-o"></i> Email</button><button type="button" class="dlr-wa"><i class="fa fa-whatsapp"></i> WhatsApp</button>'+
   '<span class="dlr-col-menu"><button type="button" class="dlr-cols"><i class="fa fa-eye"></i> Column Visibility</button><span class="dlr-col-popup"></span></span>';
   wrap.insertBefore(bar,table.parentNode===wrap?table:table.parentNode);
   var rows=Array.from(table.querySelectorAll('tbody tr')), search=bar.querySelector('.dlr-search'), size=bar.querySelector('.dlr-page-size');
   function filter(){var s=search.value.toLowerCase(),lim=parseInt(size.value)||50,c=0;var heads2=Array.from(table.querySelectorAll('thead th')).map(function(x){return x.textContent.toLowerCase()});var di=heads2.findIndex(function(x){return x.indexOf('date')>-1||x.indexOf('time')>-1});var from=bar.querySelector('.dlr-from').value,to=bar.querySelector('.dlr-to').value;rows.forEach(function(r){var ok=r.textContent.toLowerCase().indexOf(s)>-1;if(ok&&di>=0&&(from||to)){var d=new Date((r.children[di]?r.children[di].textContent:'').trim());if(!isNaN(d)){if(from&&d<new Date(from+'T00:00:00'))ok=false;if(to&&d>new Date(to+'T23:59:59'))ok=false;}}if(ok&&c<lim){r.style.display='';c++}else r.style.display='none';});}
   search.addEventListener('input',filter);size.addEventListener('change',filter);bar.querySelector('.dlr-from').addEventListener('change',filter);bar.querySelector('.dlr-to').addEventListener('change',filter);bar.querySelector('.dlr-range').addEventListener('change',function(){var now=new Date(),y=now.getFullYear(),v=this.value,f='',t='';if(v==='this_year'){f=y+'-01-01';t=y+'-12-31'}else if(v==='last_year'){f=(y-1)+'-01-01';t=(y-1)+'-12-31'}else if(v==='this_fy'){var sy=now.getMonth()>=3?y:y-1;f=sy+'-04-01';t=(sy+1)+'-03-31'}else if(v==='last_fy'){var sy2=(now.getMonth()>=3?y:y-1)-1;f=sy2+'-04-01';t=(sy2+1)+'-03-31'}bar.querySelector('.dlr-from').value=f;bar.querySelector('.dlr-to').value=t;filter();});filter();
   var heads=Array.from(table.querySelectorAll('thead th')); heads.forEach(function(th,i){var h=th.textContent.trim().toLowerCase(); if(/qty|quantity|balance|current|min|max|level|avg|suggested|variance|total|amount/.test(h)){Array.from(table.querySelectorAll('tbody tr')).forEach(function(r){var td=r.children[i];if(!td)return;td.classList.add('dlr-num');var n=parseNum(td.textContent);if(n!==null){var p=/amount|total/.test(h)?cPrec:qPrec;td.textContent=n.toLocaleString(undefined,{minimumFractionDigits:p,maximumFractionDigits:p});}})} if(h==='notes'||h==='note'){Array.from(table.querySelectorAll('tbody tr')).forEach(function(r){var td=r.children[i];if(!td)return;var t=td.textContent.trim();if(t&&t!=='-'){td.innerHTML='<button type="button" class="dlr-note-btn" data-note="'+t.replace(/"/g,'&quot;')+'">Note</button>';}})} });
   var popup=bar.querySelector('.dlr-col-popup');heads.forEach(function(th,i){var label=document.createElement('label');label.innerHTML='<input type="checkbox" checked data-col="'+i+'"> '+(th.textContent.trim()||('Column '+(i+1)));popup.appendChild(label)});bar.querySelector('.dlr-cols').onclick=function(){popup.classList.toggle('show')};popup.addEventListener('change',function(e){if(!e.target.matches('[data-col]'))return;var i=+e.target.dataset.col,show=e.target.checked;table.querySelectorAll('tr').forEach(function(r){if(r.children[i])r.children[i].style.display=show?'':'none'})});
   function exportFile(ext,sep,mime){var lines=[];table.querySelectorAll('tr').forEach(function(r){if(r.style.display==='none')return;var cells=Array.from(r.children).filter(function(c){return c.style.display!=='none'}).map(function(c){return '"'+c.innerText.replace(/"/g,'""')+'"'});lines.push(cells.join(sep))});var a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\n')],{type:mime}));a.download=(document.title||'dealer-report').replace(/\W+/g,'_')+'.'+ext;a.click();URL.revokeObjectURL(a.href)}
   bar.querySelector('.dlr-csv').onclick=function(){exportFile('csv',',','text/csv')};bar.querySelector('.dlr-xls').onclick=function(){exportFile('xls','\t','application/vnd.ms-excel')};bar.querySelector('.dlr-print').onclick=function(){window.print()};bar.querySelector('.dlr-pdf').onclick=function(){window.print()};bar.querySelector('.dlr-email').onclick=function(){location.href='mailto:?subject='+encodeURIComponent(document.title)+'&body='+encodeURIComponent(location.href)};bar.querySelector('.dlr-wa').onclick=function(){window.open('https://wa.me/?text='+encodeURIComponent(document.title+' '+location.href),'_blank')};
 });
 document.querySelectorAll('select.form-control, select.dlr-select').forEach(function(sel){if(sel.options.length<6||sel.dataset.dlrEnhanced)return;sel.dataset.dlrEnhanced='1';var inp=document.createElement('input');inp.className='form-control dlr-select-search';inp.placeholder='Type to filter...';sel.parentNode.insertBefore(inp,sel);inp.addEventListener('input',function(){var v=this.value.toLowerCase();Array.from(sel.options).forEach(function(o){o.hidden=v&&o.text.toLowerCase().indexOf(v)<0})});});
 document.addEventListener('click',function(e){if(e.target.classList.contains('dlr-note-btn')){document.querySelector('.dlr-modal-text').textContent=e.target.dataset.note;document.querySelector('.dlr-modal-backdrop').classList.add('show')}});
});
</script>
<div class="dlr-modal-backdrop"><div class="dlr-modal"><button type="button" class="dlr-modal-close" onclick="this.closest('.dlr-modal-backdrop').classList.remove('show')">×</button><h3>Note</h3><div class="dlr-modal-text"></div></div></div>
@endonce
